document.addEventListener("DOMContentLoaded",(()=>{fetch("/api/get-sponsors").then((e=>{if(!e.ok)throw new Error(`Failed fetching sponsors! ${e.status}`);return e.json()})).then((e=>{const o=document.getElementById("example-sponsor"),t=document.getElementById("sponsors-section");for(sponsor of e){const e=o.cloneNode(!0);e.removeAttribute("id"),e.classList.remove("d-none");const n=e.querySelector("img");n&&(n.src=sponsor.src,n.alt=sponsor.alt),t.appendChild(e)}o.remove()})).catch((e=>{console.log(e)}))}));